    static func validate(_ value:Any,kind:String) throws {
        let schema=try AdvisoryWire.object(schemaData),defs=schema["$defs"] as! [String:Any]
        try AdvisoryWire.check(value,defs[kind] as! [String:Any],definitions:defs)
    }
    static func data<T:Encodable>(_ value:T,kind:String) throws -> Data {
        let d=try JSONEncoder().encode(value);try validate(AdvisoryWire.object(d),kind:kind);return d
    }
    static func bound(_ raw:[String:Any],access:CandidateAccess) throws {
        guard raw["instance_id"] as? String==access.forgeInstanceID,raw["project_id"] as? String==access.forgeProjectID,
              raw["repository_id"] as? String==access.repositoryID,raw["conversation_id"] as? String==access.conversationID else { throw AdvisoryError.denied }
    }
    static func fields(_ f:CandidateFields) throws {
        _=try data(f,kind:"fields")
        let arrays=[f.scope,f.exclusions,f.acceptance_criteria,f.architecture_constraints,f.dependencies]
        let texts=[f.title,f.objective,f.business_value,f.engineering_value,f.architectural_value,f.rationale]+arrays.flatMap{$0}
        guard !f.scope.isEmpty,!f.acceptance_criteria.isEmpty,f.acceptance_criteria.allSatisfy({$0.trimmingCharacters(in:.whitespacesAndNewlines).count>=20}),
              arrays.allSatisfy({Set($0).count==$0.count}),texts.allSatisfy({!$0.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty && safe($0)}) else { throw AdvisoryError.invalid }
        let p=f.effect_policy,paths=p.read_paths+p.write_paths
        guard !p.read_paths.isEmpty,paths.allSatisfy({safePath($0)}),Set(p.read_paths).count==p.read_paths.count,Set(p.write_paths).count==p.write_paths.count,
              (p.delivery=="EVIDENCE_ONLY" ? p.write_paths.isEmpty:!p.write_paths.isEmpty),
              p.mode != "READ_ONLY_ASSESSMENT" || p.delivery=="EVIDENCE_ONLY",
              p.mode != "DOCUMENTATION_ONLY" || p.delivery=="GIT",
              p.mode != "BOUNDED_REPOSITORY_CHANGE" || p.delivery=="GIT" else { throw AdvisoryError.invalid }
        if ["DOCUMENTATION_ONLY","ARCHITECTURE_DESIGN_ONLY"].contains(p.mode) {
            guard p.write_paths.allSatisfy({path in !path.hasSuffix("/") && [".md",".txt",".rst",".adoc",".mmd",".puml"].contains(where:path.hasSuffix)}) else { throw AdvisoryError.invalid }
        }
    }
    static func safe(_ text:String) -> Bool {
        !text.contains("<") && !text.contains(">") && text.unicodeScalars.allSatisfy{$0.value>=32 || $0=="\n" || $0=="\t"} &&
        text.range(of:"https?://[^/\\s]+:[^/\\s]+@|(?:bearer\\s+|api[_-]?key\\s*[:=]|password\\s*[:=]|sk-[A-Za-z0-9])",options:[.regularExpression,.caseInsensitive])==nil
    }
    static func safePath(_ path:String) -> Bool {
        let reserved=[".git",".github",".codex",".agents",".engineering",".ssh",".aws",".env",".gitconfig",".gitattributes",".gitmodules","agents.md","secrets","credentials"]
        guard path.range(of:"^[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)*/?$",options:.regularExpression) != nil else { return false }
        return path.split(separator:"/").allSatisfy{!reserved.contains($0.lowercased()) && !$0.lowercased().hasPrefix(".env.") && !$0.hasSuffix(".")}
    }
    static func source(_ data:Data,turn:String) throws -> CandidateSource {
        let raw=try AdvisoryWire.object(data);try validate(raw,kind:"source_read")
        let v=try AdvisoryWire.decode(raw,as:CandidateSourceRead.self).source
        guard v.turn_id==turn,[v.turn_id,v.session_id,v.invocation_id].allSatisfy(WorklistWire.identifier),safe(v.advice_summary),Set(v.selected_sources.map(\.source_id)).count==v.selected_sources.count else { throw AdvisoryError.invalid };return v
    }
    static func proposal(_ raw:[String:Any],access:CandidateAccess,id:String,revision:Int) throws -> CandidateProposal {
        try validate(raw,kind:"proposal");try bound(raw,access:access)
        let p=try AdvisoryWire.decode(raw,as:CandidateProposal.self)
        var unsigned=raw;unsigned.removeValue(forKey:"proposal_digest")
        guard access.proposalIDs.contains(id),p.proposal_id==id,p.proposal_revision==revision,p.principal_reference==access.forgeInstanceID+":"+access.actorID,
              try AdvisoryWire.digest(unsigned)==p.proposal_digest else { throw AdvisoryError.invalid }
        try fields(p.fields)
        return p
    }
    static func capability(_ data:Data,access:CandidateAccess) throws -> CandidateCapability {
        let raw=try AdvisoryWire.object(data);try validate(raw,kind:"capability");try bound(raw,access:access)
        let c=try AdvisoryWire.decode(raw,as:CandidateCapability.self)
        guard c.proposal_ids==access.proposalIDs,c.maximum_registrations==access.maximumRegistrations else { throw AdvisoryError.invalid };return c
    }
    static func saved(_ data:Data,access:CandidateAccess,request:CandidateSaveRequest) throws -> CandidateProposal {
        let raw=try AdvisoryWire.object(data);try validate(raw,kind:"saved")
        let p=try proposal(raw["proposal"] as! [String:Any],access:access,id:request.proposal_id,revision:request.expected_revision+1)
        guard matches(p,request) else { throw AdvisoryError.invalid };return p
    }
    static func matches(_ p:CandidateProposal,_ r:CandidateSaveRequest) -> Bool {
        p.instance_id==r.instance_id && p.project_id==r.project_id && p.repository_id==r.repository_id && p.conversation_id==r.conversation_id && p.proposal_id==r.proposal_id && p.proposal_revision==r.expected_revision+1 && p.fields==r.fields && p.source.turn_id==r.turn_id && p.source.context_revision==r.context_revision && p.source.conversation_revision==r.expected_conversation_revision
    }
    static func registration(_ raw:[String:Any],access:CandidateAccess,id:String,expected:CandidateRegistrationRequest?=nil) throws -> CandidateRegistration {
        try validate(raw,kind:"registration")
        let v=try AdvisoryWire.decode(raw,as:CandidateRegistration.self),r=v.original_receipt,c=v.current
        let key:[Any]=[access.forgeInstanceID+":"+access.actorID,access.forgeProjectID,access.repositoryID,access.conversationID,id,r.proposal_revision]
        guard access.proposalIDs.contains(id),r.principal_reference==access.forgeInstanceID+":"+access.actorID,WorklistWire.identifier(r.operation_id),
              try AdvisoryWire.digest(key)==r.registration_key,
              try AdvisoryWire.digest((raw["original_receipt"] as! [String:Any])["candidate"]!)==r.candidate_digest,
              try AdvisoryWire.digest((raw["current"] as! [String:Any])["candidate"]!)==c.candidate_digest,
              c.candidate.id==r.candidate.id,c.candidate.recommendation_id==r.recommendation_id,r.candidate.recommendation_id==r.recommendation_id,
              safe(r.rationale),safe(r.candidate.title),safe(c.candidate.title),safe(r.candidate.objective),safe(c.candidate.objective) else { throw AdvisoryError.invalid }
        if let e=expected {
            guard r.proposal_digest==e.proposal_digest,r.proposal_revision==e.proposal_revision,r.source.context_revision==e.context_revision else { throw AdvisoryError.invalid }
        }
        return v
    }
    static func correlate(_ value:CandidateRegistration,_ p:CandidateProposal) throws {
        let r=value.original_receipt,f=p.fields,c=r.candidate
        guard r.proposal_digest==p.proposal_digest,r.proposal_revision==p.proposal_revision,r.source==p.source,r.rationale==f.rationale,
              c.title==f.title,c.objective==f.objective,c.scope==f.scope,c.acceptance_criteria==f.acceptance_criteria,
              c.architecture_constraints==f.architecture_constraints+f.exclusions.map({"EXCLUDED: "+$0}),c.dependencies==f.dependencies,c.effect_policy==f.effect_policy else { throw AdvisoryError.invalid }
    }
    static func preview(_ data:Data,access:CandidateAccess,id:String,revision:Int) throws -> CandidatePreview {
        let raw=try AdvisoryWire.object(data);try validate(raw,kind:"preview")
        let p=try proposal(raw["proposal"] as! [String:Any],access:access,id:id,revision:revision)
        let v=try AdvisoryWire.decode(raw,as:CandidatePreview.self)
        guard v.latest_revision>=revision else { throw AdvisoryError.invalid }
        if let r=raw["registration"] as? [String:Any] {
            let observed=try registration(r,access:access,id:id)
            try correlate(observed,p)
        }
        return v
    }
}
